--[[
    Credits: https://github.com/overextended/ox_lib/blob/main/resource/version/server.lua
    License: GNU Lesser General Public v3.0 (https://github.com/overextended/ox_lib/blob/main/LICENSE)
]]
local function checkVersion(resourceName)
    logger:trace("checkVersion(%s)", resourceName)
    local p = promise.new()

    local currentVersion = GetResourceMetadata(resourceName, "version", 0)

    if currentVersion then
        currentVersion = currentVersion:match("%d+%.%d+%.%d+")
    end

    if not currentVersion then
        p:resolve(nil)
        return p
    end

    local handleRequest = function(status, response)
        if 200 ~= status then
            p:resolve(nil)
            return
        end

        response = json.decode(response)
        if response.prerelease then
            p:resolve(nil)
            return
        end

        local latestVersion = response.tag_name:gsub("v", ""):match("%d+%.%d+%.%d+")
        if not latestVersion then
            p:resolve(nil)
            return
        end

        local data = {
            upToDate = true,
            url = response.html_url,
            sCurrent = currentVersion,
            sLatest = latestVersion,
            current = { string.strsplit(".", currentVersion) },
            latest = { string.strsplit(".", latestVersion) },
        }

        if latestVersion == currentVersion then
            p:resolve(data)
            return
        end

        for i = 1, #data.current do
            local current = tonumber(data.current[i])
            local minimum = tonumber(data.latest[i])

            if current ~= minimum then
                if current < minimum then
                    data.upToDate = false
                    p:resolve(data)

                    return
                else
                    break
                end
            end
        end

        p:resolve(data)
    end

    SetTimeout(1000, function()
        PerformHttpRequest(
            "https://api.github.com/repos/DevDaddyJacob-FiveM/" .. resourceName .. "/releases/latest",
            handleRequest,
            "GET"
        )
        -- if nil == DEV_DATA[resourceName] then
        --     handleRequest(400, nil)
        -- else
        --     handleRequest(DEV_DATA[resourceName]["status"], DEV_DATA[resourceName]["response"])
        -- end
    end)

    return p
end

if Config["VersionCheck"] then
    Citizen.CreateThread(function()
        Citizen.Wait(3500)
        logger:debug("Checking script versions...")

        local targetResources = {}

        for i = 1, GetNumResources(), 1 do
            local resource = GetResourceByFindIndex(i)

            if
                nil ~= resource
                and "ddj_" == resource:sub(1, 4)
                and "DevDaddyJacob" == GetResourceMetadata(resource, "author", 0)
            then
                targetResources[#targetResources + 1] = resource
            end
        end
        logger:debug("Found x%d resources to check", #targetResources)

        local versions = {}

        for _, resource in ipairs(targetResources) do
            local rawData = Citizen.Await(checkVersion(resource))
            logger:trace("resource: %s, rawData: %s", resource, json.encode(rawData))
            
            versions[resource] = rawData
        end

        local longestName = #("Script")
        local longestCurrent = #("Current")
        local longestLatest = #("Latest")

        for resource, data in pairs(versions) do
            logger:trace("resource: %s, data: %s", resource, json.encode(data))
            if nil == data then
                goto continue
            end

            if #resource > longestName then
                longestName = #resource
            end
            
            if #data.current > longestCurrent then
                longestCurrent = #data.sCurrent
            end
            
            if #data.sLatest > longestLatest then
                longestLatest = #data.sLatest
            end

            ::continue::
        end

        local r = function(str, len)
            return str:rep(len)
        end

        logger:trace("versions: %s", json.encode(versions))
        local message = {
            ("╔═%s═╤═%s═╤═%s═╗"):format(
                r("═", longestName),
                r("═", longestCurrent),
                r("═", longestLatest)
            ),
            ("║ Script%s │ Current%s │ Latest%s ║"):format(
                r(" ", longestName - #("Script")),
                r(" ", longestCurrent - #("Current")),
                r(" ", longestLatest - #("Latest"))
            ),
            ("╠═%s═╪═%s═╪═%s═╣"):format(
                r("═", longestName),
                r("═", longestCurrent),
                r("═", longestLatest)
            ),
        }


        for resource, data in pairs(versions) do
            if nil == data then
                goto continue
            end

            message[#message + 1] = ("║ %s%s │ %s%s │ %s%s ║"):format(
                resource, r(" ", longestName - #resource),
                data.sCurrent, r(" ", longestCurrent - #data.sCurrent),
                data.sLatest, r(" ", longestLatest - #data.sLatest)
            )

            ::continue::
        end

        message[#message + 1] = ("╚═%s═╧═%s═╧═%s═╝"):format(
            r("═", longestName),
            r("═", longestCurrent),
            r("═", longestLatest)
        )

        for _, line in ipairs(message) do
            print("  " .. line)
        end

    end)
end